  tiles(new String[]{"总电压","电池电流","实时功率","电芯压差"},0,4);tiles(new String[]{"电芯T1温度","电芯T2温度","电芯T3温度","MOS 温度"},4,4);
  LinearLayout extra=card();flagsView=label("MOS 状态：未知",12,MUT,false);extra.addView(flagsView);addCard(extra);
