 void tiles(String[] labels,int start,int cols){LinearLayout row=new LinearLayout(this);for(int i=0;i<labels.length;i++){LinearLayout t=card();t.setPadding(dp(8),dp(10),dp(7),dp(10));TextView name=label(labels[i],11,MUT,false);name.setSingleLine(true);name.setAutoSizeTextTypeUniformWithConfiguration(8,11,1,android.util.TypedValue.COMPLEX_UNIT_SP);t.addView(name,new LinearLayout.LayoutParams(-1,dp(18)));gap(t,6);TextView value=label("—",18,FG,true);value.setSingleLine(true);value.setAutoSizeTextTypeUniformWithConfiguration(10,19,1,android.util.TypedValue.COMPLEX_UNIT_SP);t.addView(value,new LinearLayout.LayoutParams(-1,dp(27)));values[start+i]=value;LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i>0)p.leftMargin=dp(7);row.addView(t,p);}for(int i=labels.length;i<cols;i++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,1,1);p.leftMargin=dp(7);row.addView(new View(this),p);}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(9);body.addView(row,p);}
