  LinearLayout legend=new LinearLayout(this);legend.setGravity(Gravity.CENTER);legend.addView(label("━ 行驶速度 km/h",11,BLUE,false));TextView e=label("   ━ 平均耗电 Wh/km",11,AMBER,false);legend.addView(e);hero.addView(legend);trend=new Trend(this);hero.addView(trend,new LinearLayout.LayoutParams(-1,dp(145)));TextView help=label("近120秒 · 双独立刻度 · 点击或横向拖动查看数值",11,MUT,false);hero.addView(help);addCard(hero);
