 void val(int i,String text,int color){if(values[i]!=null){values[i].setText(text);values[i].setTextColor(color);}}
 void stateBadge(TextView t,String text,boolean good){t.setText(text);t.setTextColor(good?TEAL:MUT);t.setBackground(bg(good?0xff263723:BORDER));}
 void updateOverview(JSONObject j){boolean valid=j.optBoolean("bmsValid"),demo=j.optBoolean("demo");stateBadge(linkBadge,demo?"演示":valid?"已连接":"无有效数据",valid&&!demo);ring.soc=j.optDouble("soc",Double.NaN);ring.invalidate();capacity.setText(f(j,"ah",1)+" Ah");socBar.setProgress(Double.isFinite(ring.soc)?(int)Math.round(Math.max(0,Math.min(100,ring.soc))*10):0);String address=service.ble.g!=null?service.ble.g.getDevice().getAddress():"—";source.setText(demo?"来源：模拟数据":"来源："+address);val(0,f(j,"voltage",1)+" V",FG);val(1,f(j,"current",1)+" A",BLUE);val(2,f(j,"power",0)+" W",j.optDouble("power",0)<0?RED:FG);val(3,f(j,"delta",3)+" V",FG);JSONArray a=j.optJSONArray("temps");for(int i=0;i<3;i++){double v=a==null?Double.NaN:a.optDouble(i,Double.NaN);val(4+i,(Double.isFinite(v)?String.format(Locale.US,"%.1f",v):"—")+" °C",TEAL);}val(7,f(j,"mos",1)+" °C",AMBER);flagsView.setText(flags(j));}
 void updateGps(JSONObject j){boolean valid=j.optBoolean("gpsValid"),demo=j.optBoolean("demo");stateBadge(gpsBadge,demo?"演示":!service.gps?"未开启":valid?"定位正常":"等待定位",valid&&!demo);speedValue.setText(f(j,"speed",0));val(0,f(j,"km",2)+" km",FG);val(1,f(j,"maxSpeed",0)+" km/h",BLUE);val(2,f(j,"eff",1)+" Wh/km",FG);val(3,f(j,"range",0)+" km",TEAL);val(4,f(j,"accuracy",0)+" m",FG);trend.samples=service.history.copy();trend.invalidate();}
 String flags(JSONObject j){int x=j.optInt("mosFlags",-1);if(x<0)return "MOS 状态：未知";return "充电MOS "+((x&64)!=0?"开":"关")+" / 放电MOS "+((x&128)!=0?"开":"关")+" / 预放电 "+((x&32)!=0?"开":"关")+"\n原始告警/保护/故障："+j.optString("alarm","—")+" / "+j.optString("protection","—")+" / "+j.optString("fault","—");}
 String f(JSONObject j,String key,int dec){double n=j.optDouble(key,Double.NaN);return Double.isFinite(n)?String.format(Locale.US,"%."+dec+"f",n):"—";}
 final Runnable refresh=new Runnable(){public void run(){if(service!=null){JSONObject j=service.snapshot();status.setText((service.demo?"● 演示 · ":j.optBoolean("bmsValid")?"● ":"○ ")+service.status+((j.optBoolean("bmsValid")||service.demo)?" · 1Hz 采样":""));status.setTextColor(service.demo?AMBER:j.optBoolean("bmsValid")?TEAL:MUT);if(ring!=null)updateOverview(j);if(trend!=null)updateGps(j);if(cellText!=null){JSONArray a=j.optJSONArray("cells");StringBuilder s=new StringBuilder("20 串电芯 · Δ "+f(j,"delta",3)+" V\n\n");double min=99,max=0;if(a!=null&&a.length()==20){for(int i=0;i<20;i++){min=Math.min(min,a.optDouble(i));max=Math.max(max,a.optDouble(i));}}for(int i=0;i<20;i++){double n=a!=null?a.optDouble(i,Double.NaN):Double.NaN;s.append(String.format(Locale.US,"%02d  %s %s   ",i+1,Double.isFinite(n)?String.format(Locale.US,"%.3f",n):"—",n==min?"↓":n==max?"↑":" "));if(i%2==1)s.append('\n');}cellText.setText(s.toString());}updateDevices();}h.postDelayed(this,500);}};
 class SocRing extends View {
  double soc=Double.NaN;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);SocRing(Context c){super(c);}
  protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.max(1,Math.min(cx,cy)-dp(7));RectF box=new RectF(cx-r,cy-r,cx+r,cy+r);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(8));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(BORDER);c.drawCircle(cx,cy,r,p);if(Double.isFinite(soc)){p.setColor(TEAL);c.drawArc(box,-90,(float)(360*Math.max(0,Math.min(100,soc))/100),false,p);}p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextSize(Math.min(dp(29),r*.56f));p.setColor(FG);c.drawText(Double.isFinite(soc)?String.format(Locale.US,"%.2f",soc):"—",cx,cy+dp(3),p);p.setTypeface(Typeface.DEFAULT);p.setTextSize(dp(12));p.setColor(MUT);c.drawText("%",cx,cy+dp(22),p);}
 }
 class Trend extends View {
  List<TripHistory.Sample> samples=Collections.emptyList();final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);long selected=-1;float downX,downY;Trend(Context c){super(c);setContentDescription("最近120秒行驶速度和平均耗电曲线，点击查看数值");}
  float left(){return dp(30);}float right(){return getWidth()-dp(30);}float top(){return dp(23);}float bottom(){return getHeight()-dp(25);}
  long end(){return samples.isEmpty()?SystemClock.elapsedRealtime():samples.get(samples.size()-1).at;}long start(){return end()-TripHistory.WINDOW_MS;}
  float x(long at){return left()+(right()-left())*(at-start())/TripHistory.WINDOW_MS;}
  double scale(boolean speed){double max=1;for(TripHistory.Sample s:samples){double n=speed?s.speed:s.efficiency;if(Double.isFinite(n))max=Math.max(max,n);}return Math.max(10,Math.ceil(max/10)*10);}
  float y(double v,double max){return bottom()-(bottom()-top())*(float)Math.max(0,Math.min(1,v/max));}
  void text(Canvas c,String t,float x,float y,int color,Paint.Align align){p.setColor(color);p.setStyle(Paint.Style.FILL);p.setTextAlign(align);p.setTextSize(dp(10));c.drawText(t,x,y,p);}
  void line(Canvas c,boolean speed,double max,int color){p.setColor(color);p.setStrokeWidth(dp(2));p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);TripHistory.Sample prev=null;for(TripHistory.Sample s:samples){double v=speed?s.speed:s.efficiency;if(!Double.isFinite(v)){prev=null;continue;}if(prev!=null&&s.at-prev.at<=3000){double a=speed?prev.speed:prev.efficiency;c.drawLine(x(prev.at),y(a,max),x(s.at),y(v,max),p);}else{c.drawPoint(x(s.at),y(v,max),p);}prev=s;}p.setStyle(Paint.Style.FILL);}
  protected void onDraw(Canvas c){double sm=scale(true),em=scale(false);for(int i=0;i<=3;i++){float yy=top()+(bottom()-top())*i/3f;p.setColor(BORDER);p.setStrokeWidth(dp(1));c.drawLine(left(),yy,right(),yy,p);text(c,String.format(Locale.US,"%.0f",sm*(3-i)/3),left()-dp(4),yy+dp(3),BLUE,Paint.Align.RIGHT);text(c,String.format(Locale.US,"%.0f",em*(3-i)/3),right()+dp(4),yy+dp(3),AMBER,Paint.Align.LEFT);}c.save();c.clipRect(left(),top(),right()+1,bottom()+1);line(c,true,sm,BLUE);line(c,false,em,AMBER);c.restore();text(c,"-120s",left(),getHeight()-dp(6),MUT,Paint.Align.LEFT);text(c,"现在",right(),getHeight()-dp(6),MUT,Paint.Align.RIGHT);TripHistory.Sample hit=null;long diff=Long.MAX_VALUE;boolean any=false;for(TripHistory.Sample s:samples){if(Double.isFinite(s.speed)||Double.isFinite(s.efficiency))any=true;if(selected>=start()&&selected<=end()&&Math.abs(s.at-selected)<diff){diff=Math.abs(s.at-selected);hit=s;}}if(!any)text(c,"等待有效数据",getWidth()/2f,(top()+bottom())/2,MUT,Paint.Align.CENTER);if(hit!=null){float xx=x(hit.at);p.setColor(MUT);p.setStrokeWidth(dp(1));c.drawLine(xx,top(),xx,bottom(),p);String sp=Double.isFinite(hit.speed)?String.format(Locale.US,"%.1f",hit.speed):"—",ef=Double.isFinite(hit.efficiency)?String.format(Locale.US,"%.1f",hit.efficiency):"—";text(c,sp+" km/h  /  "+ef+" Wh/km",getWidth()/2f,dp(15),FG,Paint.Align.CENTER);}}
  void select(float xx){float fraction=Math.max(0,Math.min(1,(xx-left())/Math.max(1,right()-left())));selected=start()+(long)(fraction*TripHistory.WINDOW_MS);invalidate();}
  public boolean onTouchEvent(android.view.MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:downX=e.getX();downY=e.getY();select(downX);return true;case MotionEvent.ACTION_MOVE:if(Math.abs(e.getX()-downX)>Math.abs(e.getY()-downY)&&Math.abs(e.getX()-downX)>dp(5))getParent().requestDisallowInterceptTouchEvent(true);select(e.getX());return true;case MotionEvent.ACTION_UP:select(e.getX());getParent().requestDisallowInterceptTouchEvent(false);performClick();return true;case MotionEvent.ACTION_CANCEL:getParent().requestDisallowInterceptTouchEvent(false);return true;}return super.onTouchEvent(e);}
  public boolean performClick(){super.performClick();return true;}
 }
